NODE_PATH=$(npm root -g) node -e "
const db = require('better-sqlite3')('/workspace/world.db');
// Get max cart_item_id to determine next ID
const maxItem = db.prepare(\"SELECT cart_item_id FROM cart_items ORDER BY cart_item_id DESC LIMIT 1\").get();
console.log('Max cart_item_id:', maxItem);
// Check current cart items for Alicia
const items = db.prepare(\"SELECT * FROM cart_items WHERE cart_id = 'CART-user_1b350225'\").all();
console.log('Current cart items:', items);
"

NODE_PATH=$(npm root -g) node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const cartId = 'CART-user_1b350225';
const customerId = 'user_1b350225';
const productId = 'PROD-73FAB4';
const newItemId = 'CI-0032';
const price = 88;

// Insert cart item
db.prepare(\"INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id) VALUES (?, ?, ?, ?, ?, ?, ?)\")
  .run(newItemId, cartId, customerId, productId, 1, 0, null);

// Update cart totals
const shippingCost = 6; // standard shipping
db.prepare(\"UPDATE carts SET subtotal = ?, shipping_option = 'standard', shipping_cost = ?, total = ?, item_ids_json = ? WHERE cart_id = ?\")
  .run(price, shippingCost, price + shippingCost, JSON.stringify([newItemId]), cartId);

// Verify
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = ?\").get(cartId);
const items = db.prepare(\"SELECT * FROM cart_items WHERE cart_id = ?\").all(cartId);
console.log('Updated cart:', JSON.stringify(cart, null, 2));
console.log('Cart items:', JSON.stringify(items, null, 2));
"

NODE_PATH=$(npm root -g) node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const cartId = 'CART-user_1b350225';
const itemId = 'CI-0032';
const unitPrice = 88;
const newQty = 2;
const newSubtotal = unitPrice * newQty;
const shippingCost = 6;

// Update cart item quantity
db.prepare('UPDATE cart_items SET quantity = ? WHERE cart_item_id = ?').run(newQty, itemId);

// Update cart totals
db.prepare('UPDATE carts SET subtotal = ?, total = ? WHERE cart_id = ?')
  .run(newSubtotal, newSubtotal + shippingCost, cartId);

// Verify
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all(cartId);
console.log('Updated cart:', JSON.stringify(cart, null, 2));
console.log('Cart items:', JSON.stringify(items, null, 2));
"
